parameters.jsCode:
// Parse LLM triage output and merge with original email metadata
const items = $input.all();

return items.map((item, index) => {
  const original = $('Fetch Email & Task Batch').all()[index]?.json || {};
  let rawContent = item.json.message?.content || item.json.choices?.[0]?.message?.content || item.json.text || '';

  // Clean markdown code blocks if present
  rawContent = rawContent.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

  let parsed = {};
  try {
    parsed = JSON.parse(rawContent);
  } catch (err) {
    // Fallback extraction regex if extra text surrounds JSON
    const match = rawContent.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        parsed = JSON.parse(match[0]);
      } catch (e) {
        parsed = { parse_error: true, raw_response: rawContent };
      }
    } else {
      parsed = { parse_error: true, raw_response: rawContent };
    }
  }

  const priority = (parsed.priority || 'P2').toUpperCase();
  const urgency = (parsed.urgency || 'medium').toLowerCase();
  const category = (parsed.category || 'general').toLowerCase();
  const isUrgent = priority === 'P0' || priority === 'P1' || urgency === 'high' || category === 'incident';

  return {
    json: {
      email_id: original.id || ('ITEM-' + index),
      sender: original.sender,
      subject: original.subject,
      received_at: original.received_at,
      triage: {
        category: category,
        priority: priority,
        urgency: urgency,
        action: parsed.action || 'review',
        summary: parsed.summary || original.subject,
        suggested_reply: parsed.suggested_reply || null,
        is_urgent: isUrgent
      },
      is_urgent: isUrgent,
      processed_at: new Date().toISOString()
    }
  };
});

// Dispatch high-priority alert (PagerDuty / Slack / On-call notification payload)
const urgentItems = $input.all();
return urgentItems.map(item => {
  const data = item.json;
  return {
    json: {
      status: 'ESCALATED',
      channel: '#eng-incidents',
      alert_level: 'HIGH_PRIORITY',
      email_id: data.email_id,
      subject: data.subject,
      priority: data.triage.priority,
      category: data.triage.category,
      action: data.triage.action,
      summary: data.triage.summary,
      dispatched_at: new Date().toISOString()
    }
  };
});

// Queue routine tickets to respective departments (CRM / Jira / Auto-Archive)
const routineItems = $input.all();
return routineItems.map(item => {
  const data = item.json;
  const category = data.triage.category;
  let targetQueue = 'support_general';

  if (category === 'billing') {
    targetQueue = 'finance_inbox';
  } else if (category === 'feature_request') {
    targetQueue = 'product_backlog';
  } else if (category === 'spam') {
    targetQueue = 'spam_quarantine';
  } else if (category === 'bug') {
    targetQueue = 'engineering_triage';
  }

  return {
    json: {
      status: 'QUEUED',
      destination_queue: targetQueue,
      email_id: data.email_id,
      subject: data.subject,
      priority: data.triage.priority,
      category: category,
      action: data.triage.action,
      suggested_reply: data.triage.suggested_reply,
      queued_at: new Date().toISOString()
    }
  };
});
